/// The font families.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum GFamily {
    Text,
    Display,
    Mono,
}

impl GFamily {
    pub const fn name(self) -> &'static str {
        match self {
            GFamily::Text => "IBM Plex Sans",
            GFamily::Display => "IBM Plex Sans Condensed",
            GFamily::Mono => "IBM Plex Mono",
        }
    }
}

